const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const aiTitle='I modelli open-weight metteranno sotto pressione l’AI chiusa.',tariffTitle='I nuovi dazi ridurranno la competitività di AliExpress, favorendo Amazon.';
const aiNodes=[['TESI DI PARTENZA','Open-weight sempre più competitivi','Il punto da cui parti'],['CONSEGUENZA','Si riduce il vantaggio dei modelli chiusi','Ipotesi da verificare'],['PASSAGGIO CHIAVE','Le aziende migrano verso open-weight','2 ipotesi nascoste'],['CONSEGUENZA','Pressione su domanda e pricing','Effetto indiretto'],['CONSEGUENZA','Più inference privata','Scenario condizionale'],['SCENARIO ALTERNATIVO','I modelli chiusi alzano l’asticella','La risposta dei concorrenti']];
const tariffNodes=[['TESI DI PARTENZA','I dazi aumentano il costo di AliExpress','Il punto da cui parti'],['CONSEGUENZA','Si riduce il vantaggio di prezzo','Assorbimento da verificare'],['PASSAGGIO CHIAVE','Gli acquisti passano ad Amazon','2 ipotesi nascoste'],['CONSEGUENZA','Impatto sui ricavi di Amazon','Dimensione da verificare'],['CONSEGUENZA','L’effetto emerge nel trimestre','Tempistiche incerte'],['SCENARIO ALTERNATIVO','I venditori assorbono il dazio','La risposta dei concorrenti']];
const aiDetails=[['La parità su un benchmark vale anche nei processi reali?',['Il confronto include qualità, latenza e affidabilità.','La licenza consente l’utilizzo commerciale.'],'La parità potrebbe riguardare soltanto alcuni compiti.'],['Il vantaggio dei provider chiusi dipende solo dal modello?',['Distribuzione e integrazioni non bastano a difendere il vantaggio.','Il confronto considera il costo totale.'],'Supporto e dati proprietari possono mantenere un vantaggio.'],['Un modello altrettanto capace è sufficiente per convincere un’azienda a cambiare?',['I costi di migrazione non superano il risparmio atteso.','Sicurezza e supporto sono all’altezza delle esigenze aziendali.'],'I provider chiusi potrebbero ridurre i prezzi e rendere la migrazione meno conveniente.'],['Una minore quota di mercato implica necessariamente meno ricavi?',['La migrazione è abbastanza grande da incidere sulla domanda.','La crescita del mercato non compensa la perdita di quota.'],'Un mercato in espansione può far crescere i ricavi anche con quote più basse.'],['Più inference privata significa necessariamente più GPU?',['I carichi richiedono capacità hardware aggiuntiva.','L’efficienza non compensa tutta la crescita della domanda.'],'Quantizzazione e utilizzo migliore possono contenere gli acquisti.'],['Come reagirebbero i provider chiusi?',['Hanno margini per ridurre i prezzi.','Possono differenziarsi con servizi e nuovi modelli.'],'Una risposta su prezzo e prodotto potrebbe rallentare la migrazione.']];
const tariffDetails=[['Quanto del dazio arriva al prezzo finale?',['La misura si applica ai prodotti osservati.','Il confronto usa un paniere costante.'],'I venditori potrebbero ridurre i margini.'],['Il rincaro cancella il vantaggio di prezzo?',['I venditori non assorbono interamente il costo.','Il consumatore confronta i prezzi finali.'],'AliExpress potrebbe restare più economico.'],['Perché gli acquirenti dovrebbero scegliere proprio Amazon?',['L’offerta sostitutiva è disponibile su Amazon.','Gli acquisti non si spostano soprattutto verso altri concorrenti.'],'Altri marketplace, negozi locali o meno acquisti possono assorbire la domanda.'],['Lo spostamento emerge nei ricavi totali?',['Il volume supera il rumore del trimestre.','Altri fattori non spiegano da soli la crescita.'],'Ricavi in aumento non dimostrano che la causa siano i dazi.'],['Le abitudini cambiano entro il trimestre?',['Il dazio entra in vigore abbastanza presto.','La reazione non richiede molti mesi.'],'La direzione può essere corretta ma manifestarsi più tardi.'],['Per quanto tempo i venditori possono sacrificare i margini?',['I margini permettono di assorbire il dazio.','La concorrenza incentiva prezzi bassi.'],'Il rincaro potrebbe essere limitato ad alcune categorie.']];
const positions=[[4,146],[36,38],[68,38],[68,210],[36,291],[4,291]];
let selected=2,kind='ai',title=aiTitle,view='map',tab='map',zoom=1,friction=30,annotation='',deadline='2031-09-18',saved=[];
try{saved=JSON.parse(localStorage.getItem('nesso-demo-v1')||'[]');if(!Array.isArray(saved))saved=[]}catch{}
const mapMarkup=$('#content').innerHTML,canvasMarkup=$('#canvas').innerHTML;
const criteriaAI=[{name:'Parità tecnica',weight:40,rule:'≥95%: 40 punti · da 90% a <95%: 32 · <90%: 0.',definition:'Mediana dei due migliori open-weight rispetto ai closed su una suite demo fissa: 20 task di coding e 20 di assistenza, stesso budget e latenza.',value:92,unit:'%',points:32},{name:'Vantaggio economico',weight:30,rule:'TCO ≤70%: 30 punti · >70% e ≤85%: 21 · >85%: 0.',definition:'TCO triennale privato / costo API closed su due workload fissi; include hardware, energia e personale.',value:78,unit:'%',points:21},{name:'Migrazione effettiva',weight:30,rule:'Quota ≥25%: 30 punti · da 10% a <25%: 17 · <10%: 0.',definition:'Quota dei workload eleggibili in produzione privata nella coorte demo fissa di 20 aziende.',value:18,unit:'%',points:17}];
const criteriaTariff=[{name:'Rincaro effettivo',weight:40,rule:'Rincaro ≥15%: 40 punti · da 5% a <15%: 32 · <5%: 0.',definition:'Variazione del prezzo finale mediano nel paniere demo di 50 prodotti AliExpress rispetto al trimestre precedente.',value:9,unit:'%',points:32},{name:'Trasferimento ad Amazon',weight:30,rule:'Quota ≥40%: 30 punti · da 20% a <40%: 21 · <20%: 0.',definition:'Spesa persa da AliExpress trasferita ad Amazon nel panel demo fisso di 200 acquirenti.',value:28,unit:'%',points:21},{name:'Impatto nel trimestre',weight:30,rule:'Incremento ≥1%: 30 punti · da 0,3% a <1%: 17 · <0,3%: 0.',definition:'Incremento ricavi retail UE attribuibile, stimato con gruppo di controllo demo entro la scadenza.',value:.5,unit:'%',points:17}];
function nodes(){return kind==='custom'?[['TESI DI PARTENZA',title,'Inserita da te'],['IPOTESI','La premessa è misurabile','Da definire'],['PASSAGGIO CHIAVE','Esiste un meccanismo causale','Da definire'],['CONSEGUENZA','L’effetto è osservabile','Da definire'],['TEMPISTICHE','L’effetto arriva entro la scadenza','Da definire'],['SCENARIO ALTERNATIVO','Un’altra causa spiega l’esito','Da esplorare']]:kind==='ai'?aiNodes:tariffNodes}
function details(i=selected){return kind==='custom'?['Quale osservazione concreta ti farebbe cambiare idea?',['Occorre definire un meccanismo causale verificabile.','Occorre distinguere correlazione e causa.'],'Questo è uno schema guidato: la demo non genera analisi AI su testi liberi.']:(kind==='ai'?aiDetails:tariffDetails)[i]}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').showModal();$$('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close())}
function head(label){return `<div class="modal-top"><span class="eyebrow">${label}</span><button class="icon-btn" data-close aria-label="Chiudi finestra">×</button></div>`}
function persist(){try{localStorage.setItem('nesso-demo-v1',JSON.stringify(saved));return true}catch{toast('Memoria non disponibile: salvataggio solo per questa sessione.');return false}}
function renderGraph(){const n=nodes();$('#graph').style.transform=`scale(${zoom})`;$('#graph').innerHTML=`<svg viewBox="0 0 1000 415" preserveAspectRatio="none"><defs><marker id="arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#bac8ad"/></marker></defs><g fill="none" stroke="#c5cfba" stroke-width="1.3" marker-end="url(#arrow)"><path d="M290 194 H316 Q326 194 326 180 V100 Q326 85 340 85 H359"/><path d="M610 85 H679"/><path d="M805 150 V208"/><path d="M745 152 V175 Q745 187 729 187 H500 Q485 187 485 201 V289"/><path d="M165 251 V289" stroke-dasharray="4 4"/><path d="M360 344 H291" stroke-dasharray="4 4"/></g></svg>`+n.map((x,i)=>`<button class="node ${i===0?'root':''} ${i===selected?'selected':''}" aria-pressed="${i===selected}" style="left:${positions[i][0]}%;top:${positions[i][1]}px;width:25%" data-node="${i}"><span class="node-type">${i===0?'↗':i===5?'⑂':'◈'} ${esc(x[0])}<span class="node-index">0${i+1}</span></span><strong>${esc(x[1])}</strong><span class="node-bottom ${i===2?'warning':''}">${friction!==30&&[2,3,4].includes(i)?(friction>60?'↓ Nesso indebolito':friction<30?'↑ Nesso rafforzato':'↔ Impatto moderato'):esc(x[2])} <span>↗</span></span></button>`).join('');$$('[data-node]').forEach(b=>b.onclick=()=>selectNode(+b.dataset.node));$('#zoomLabel').textContent=Math.round(zoom*100)+'%'}
function selectNode(i){if(!Number.isInteger(i)||i<0||i>5)throw Error('Nodo non valido');selected=i;if(view!=='map')showView('map');if(tab==='map')renderGraph();renderInspector();return {node:i,title:nodes()[i][1]}}
function renderInspector(){const d=details();$('#inspector').innerHTML=`<div class="inspector-header">DENTRO IL RAGIONAMENTO <span>0${selected+1} / 06</span></div><h3>${esc(nodes()[selected][1])}</h3><span class="status-tag">◇ Un passaggio da dimostrare</span><div class="challenge-card"><small>✳ LA DOMANDA SCOMODA</small><p>${esc(d[0])}</p></div><div class="detail-label">COSA STAI DANDO PER SCONTATO</div>${d[1].map(x=>`<div class="assumption">${esc(x)}</div>`).join('')}<div class="divider"></div><div class="detail-label">GUARDA ANCHE L’ALTRA STRADA</div><p>${esc(d[2])}</p><button class="button" id="challenge">Metti alla prova questo nesso <span>→</span></button><p class="source-note">${annotation?'Hai aggiunto una nota al ragionamento.':'Nessuna fonte collegata · Da verificare'}</p>`;$('#challenge').onclick=challenge}
function bindZoom(){$('#zoomIn').onclick=()=>{zoom=Math.min(1.3,zoom+.1);renderGraph()};$('#zoomOut').onclick=()=>{zoom=Math.max(.7,zoom-.1);renderGraph()};$('#zoomReset').onclick=()=>{zoom=1;renderGraph()}}
function initMap(){$('#thesisTitle').textContent=title;$('.thesis-meta').innerHTML=`<span>◷ Entro il ${new Date(deadline+'T12:00').toLocaleDateString('it-IT')}</span><span>◈ ${kind==='ai'?'Tecnologia & AI':kind==='tariff'?'Economia & consumi':'La tua intuizione'}</span><span>6 passaggi da esplorare</span>`;$('#saveTop').onclick=saveDialog;$('#editThesis').onclick=()=>newDialog(true);$('#scenario').onclick=scenarioDialog;$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;$$('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));if(tab==='map'){$('#canvas').innerHTML=canvasMarkup;renderGraph();bindZoom()}else{$('#canvas').innerHTML=`<div class="assumptions-view"><div class="eyebrow">LE CONDIZIONI CHE TENGONO IN PIEDI LA TESI</div>${[1,2,3,4].map(i=>`<button data-assumption="${i}">◇ ${esc(details(i)[1][0])}<small>Passaggio 0${i+1} · Nessuna evidenza collegata →</small></button>`).join('')}</div>`;$$('[data-assumption]').forEach(x=>x.onclick=()=>{selected=+x.dataset.assumption;renderInspector()})}});renderGraph();renderInspector();bindZoom()}
function showView(v){view=v;$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#breadTitle').textContent={map:'Laboratorio',journal:'Thinking Journal',learn:'Il tuo pensiero'}[v];if(v==='map'){$('#content').innerHTML=mapMarkup;tab='map';initMap()}if(v==='journal')renderJournal();if(v==='learn')renderLearn();$('#journalCount').textContent=String(saved.length+3).padStart(2,'0')}
function newDialog(edit=false){modal(`${head(edit?'AFFINA LA TUA TESI':'01 / THINK')}<h2>${edit?'Le parole contano.':'Da quale intuizione partiamo?'}</h2><p>Scrivi una previsione che il mondo possa confermare o smentire.</p><div class="sample-row"><button id="sampleAI">↗ AI open-weight</button><button id="sampleTariff">↗ Dazi & marketplace</button></div><label class="field" for="newText">La tua tesi</label><textarea id="newText" maxlength="500" placeholder="Secondo me, nei prossimi…">${edit?esc(title):''}</textarea><label class="field" for="newDate">Entro quando?</label><input id="newDate" type="date" value="${deadline}"><p class="source-note">I due esempi hanno mappe predefinite. Un testo libero apre uno schema guidato, senza generazione AI.</p><div class="error" id="newError"></div><div class="modal-actions"><button class="button" data-close>Annulla</button><button class="button dark" id="buildMap">Esplora la tesi →</button></div>`);$('#sampleAI').onclick=()=>{$('#newText').value=aiTitle;$('#newDate').value='2031-09-18'};$('#sampleTariff').onclick=()=>{$('#newText').value=tariffTitle;$('#newDate').value='2027-03-31'};$('#buildMap').onclick=()=>{const t=$('#newText').value.trim(),d=$('#newDate').value;if(t.length<15||!d){$('#newError').textContent='Scrivi almeno 15 caratteri e scegli una scadenza.';return}title=t;kind=t===aiTitle?'ai':t===tariffTitle?'tariff':'custom';deadline=d;friction=30;annotation='';selected=2;$('#modal').close();showView('map');toast(kind==='custom'?'Schema guidato pronto: definisci le tue ipotesi.':'Mappa pronta. Parti dal passaggio più fragile.')}}
function challenge(){const d=details();modal(`${head('03 / CHALLENGE')}<h2>Un’ipotesi, non una certezza.</h2><div class="challenge-card"><small>LA DOMANDA SCOMODA</small><p>${esc(d[0])}</p></div><p><strong>Per verificare questo passaggio</strong><br>${esc(d[1].join(' '))}</p><label class="field" for="challengeNote">Quale dato ti farebbe cambiare idea?</label><textarea id="challengeNote" maxlength="1200" placeholder="Per esempio: se i costi di migrazione superassero due anni di risparmi…">${esc(annotation)}</textarea><div class="modal-actions"><button class="button" id="tryScenario">Esplora uno scenario</button><button class="button dark" id="saveNote">Aggiungi al ragionamento</button></div>`);$('#saveNote').onclick=()=>{annotation=$('#challengeNote').value.trim();$('#modal').close();renderInspector();toast(annotation?'Nota aggiunta. Sarà inclusa nel salvataggio.':'Nota rimossa.')};$('#tryScenario').onclick=()=>{$('#modal').close();scenarioDialog()}}
function scenarioDialog(){if(kind==='custom'){toast('Gli scenari guidati sono disponibili sui due esempi predefiniti.');return}modal(`${head('WHAT IF / SCENARIO')}<h2>E se cambiasse un’ipotesi?</h2><p>${kind==='tariff'?'Quanto riescono i venditori ad assorbire il dazio?':'Quanto è difficile abbandonare il provider attuale?'}</p><div class="range-line"><label for="friction">${kind==='tariff'?'Assorbimento del costo':'Attrito di migrazione'}</label><strong id="frictionValue">${friction}/100</strong></div><input id="friction" type="range" min="0" max="100" value="${friction}"><div class="range-line"><small>Basso</small><small>Alto</small></div><div class="scenario-note" id="scenarioResult"></div><p>Regola illustrativa: sopra 60 i passaggi a valle si indeboliscono; sotto 30 si rafforzano. Non è una probabilità o una previsione quantitativa.</p><div class="modal-actions"><button class="button" id="resetScenario">Ripristina 30/100</button><button class="button orange" id="applyScenario">Applica alla mappa →</button></div>`);const update=()=>{const v=+$('#friction').value;$('#frictionValue').textContent=v+'/100';$('#scenarioResult').innerHTML=`<strong>${v>60?'↓ La catena si indebolisce':v<30?'↑ La catena si rafforza':'↔ La catena rimane condizionata'}</strong><br>${kind==='tariff'?'Più assorbimento → meno rincaro → meno trasferimento di acquisti.':'Più attrito → meno migrazione → minore pressione sui prezzi e minore domanda di inference privata.'}<br><small>Tre conseguenze collegate vengono aggiornate. La tesi resta invariata.</small>`};$('#friction').oninput=update;$('#resetScenario').onclick=()=>{$('#friction').value=30;update()};$('#applyScenario').onclick=()=>{friction=+$('#friction').value;$('#modal').close();showView('map');toast('Scenario applicato ai tre passaggi a valle.')};update()}
function saveDialog(){const custom=kind==='custom',criteria=kind==='tariff'?criteriaTariff:criteriaAI;modal(`${head('04 / SAVE · PREREGISTRAZIONE')}<h2>Prima i criteri. Poi i risultati.</h2><p>Salva una fotografia del ragionamento. Ipotesi, scenario e criteri di questa versione resteranno fissi.</p><div class="wide-note"><strong>${esc(title)}</strong><br>Scadenza: ${new Date(deadline+'T12:00').toLocaleDateString('it-IT')} · Scenario: ${friction}/100</div>${custom?'<p>Puoi conservare una bozza. Non sono ancora definiti criteri misurabili: nessun punteggio sarà assegnato.</p>':criteria.map(c=>`<div class="criteria-row"><div class="row-heading"><span>${c.name}</span><span>${c.weight} punti</span></div><p>${c.definition}</p><p><strong>${c.rule}</strong></p></div>`).join('')}<p>${custom?'La bozza rimane non valutata.':'Pesi totali: 100. Dati mancanti → non valutato. Suite e panel sono fittizi e servono a provare il flusso.'}</p><label class="check-row"><input type="checkbox" id="confirmCriteria"><span>${custom?'Conservo questa bozza per approfondirla.':'Ho letto i criteri e li fisso per questa versione.'}<br>Salvataggio locale nel browser. Nessun monitoraggio automatico.</span></label><div class="error" id="saveError"></div><div class="modal-actions"><button class="button" data-close>Continua a esplorare</button><button class="button dark" id="confirmSave">${custom?'Salva bozza':'Fissa e salva tesi'} ↗</button></div>`);$('#confirmSave').onclick=()=>{if(!$('#confirmCriteria').checked){$('#saveError').textContent='Leggi e conferma prima di salvare.';return}saved.unshift({id:Date.now().toString(),title,kind,deadline,friction,annotation,created:new Date().toISOString(),criteria:custom?[]:JSON.parse(JSON.stringify(criteria)),map:nodes().map((n,i)=>({node:[...n],details:JSON.parse(JSON.stringify(details(i)))})),verified:false});const ok=persist();$('#modal').close();showView('journal');if(ok)toast('Tesi salvata in questo browser. La versione è fissata.')}}
const samples=[{id:'sample-ai',title:aiTitle,kind:'ai',deadline:'2031-09-18',friction:30,annotation:'Separare parità tecnica e migrazione in produzione.',created:'2026-09-04T09:30:00Z',criteria:criteriaAI,verified:true,sample:true},{id:'sample-tariff',title:tariffTitle,kind:'tariff',deadline:'2027-03-31',friction:30,annotation:'Non attribuire tutta la crescita di Amazon ai dazi.',created:'2026-09-10T10:30:00Z',criteria:criteriaTariff,verified:false,sample:true},{id:'sample-week',title:'La settimana di quattro giorni migliora la retention dei team.',kind:'custom',deadline:'2027-09-18',friction:30,annotation:'Distinguere selezione delle aziende ed effetto causale.',created:'2026-09-12T10:00:00Z',criteria:[],verified:false,sample:true}];
function renderJournal(){const all=[...saved,...samples];$('#content').innerHTML=`<section class="page-heading"><div><div class="eyebrow">04 — 05 / SAVE → VERIFY</div><h1>Il mondo cambia. Le tue tesi restano.</h1><p>Un diario di ciò che pensavi, prima di sapere come sarebbe andata.</p></div><button class="button dark" id="journalNew">＋ Nuova tesi</button></section><div class="metric-grid"><div class="metric"><small>Tesi nel diario</small><strong>${String(all.length).padStart(2,'0')}</strong><small>3 esempi + ${saved.length} salvate da te</small></div><div class="metric"><small>Criteri fissati</small><strong>${String(all.filter(r=>r.criteria.length).length).padStart(2,'0')}</strong><small>Versioni conservate nel tempo</small></div><div class="metric"><small>Verifiche reali</small><strong>—</strong><small>Solo simulazioni in questa demo</small></div></div><div class="journal-list">${all.map(r=>`<article class="journal-card"><div><span class="tag ${r.verified?'':'amber'}">${r.verified?'VERIFICA SIMULATA':r.criteria.length?'CRITERI FISSATI':'BOZZA · NON VALUTATA'}</span> <span class="eyebrow">${r.sample?'ESEMPIO DEMO':'SALVATA DA TE'}</span><h3>${esc(r.title)}</h3><p>${new Date(r.created).toLocaleDateString('it-IT')} · Entro il ${new Date(r.deadline+'T12:00').toLocaleDateString('it-IT')}</p></div><div class="score">${r.verified?'70<small> /100</small>':'—'}</div><button class="button" data-record="${r.id}">${r.verified?'Leggi il feedback':'Apri tesi'} ↗</button></article>`).join('')}</div><div class="wide-note">◈ Il diario usa la memoria locale di questo browser. Gli esempi sono fittizi; nessuna raccolta di dati o fonti reali.</div>`;$('#journalNew').onclick=()=>newDialog();$$('[data-record]').forEach(b=>b.onclick=()=>{const r=all.find(r=>r.id===b.dataset.record);r.verified?verifyDialog(r):recordDialog(r)})}
function recordDialog(r){modal(`${head('VERSIONE FISSATA · '+(r.sample?'ESEMPIO DEMO':'SALVATA DA TE'))}<h2>${esc(r.title)}</h2><p>Salvata il ${new Date(r.created).toLocaleString('it-IT')} · Scadenza ${new Date(r.deadline+'T12:00').toLocaleDateString('it-IT')}</p><div class="scenario-note"><strong>Fotografia del ragionamento</strong><br>Scenario: ${r.friction}/100.<br>${esc(r.annotation||'Nessuna nota aggiuntiva.')}</div>${r.criteria.map(c=>`<div class="criteria-row"><div class="row-heading"><span>▣ ${esc(c.name)}</span><span>${c.weight} punti</span></div><p>${esc(c.definition)}</p><p>${esc(c.rule)}</p></div>`).join('')}${r.criteria.length?'<p>Il feedback userà queste soglie. Dati mancanti: non valutato.</p>':'<p>Nessun criterio definito. Questa bozza non può ricevere un punteggio.</p>'}<div class="modal-actions"><button class="button" id="reopenRecord">Esplora una nuova versione</button>${r.criteria.length?'<button class="button orange" id="verifyRecord">Simula verifica →</button>':''}</div>`);$('#reopenRecord').onclick=()=>{title=r.title;kind=r.kind;deadline=r.deadline;friction=r.friction;annotation=r.annotation;$('#modal').close();showView('map');toast('Nuova esplorazione. La versione salvata resta invariata.')};if(r.criteria.length)$('#verifyRecord').onclick=()=>{r.verified=true;if(!r.sample)persist();$('#modal').close();showView('journal');verifyDialog(r)}}
function verifyDialog(r){const score=r.criteria.reduce((s,c)=>s+c.points,0);modal(`${head('05 / VERIFY · ESITO INTERAMENTE SIMULATO')}<h2>La direzione regge.<br>Il meccanismo, solo in parte.</h2><div class="score-large">${score}<small> / 100</small></div><span class="status-tag">Parzialmente supportata · Esempio fittizio</span>${r.criteria.map(c=>`<div class="criteria-row"><div class="row-heading"><span>${esc(c.name)} · ${c.value}${c.unit}</span><span>${c.points}/${c.weight}</span></div><div class="bar"><span style="width:${c.points/c.weight*100}%"></span></div><p>${esc(c.rule)}</p></div>`).join('')}<div class="scenario-note"><strong>Dove si è spezzata la catena?</strong><br>${r.kind==='ai'?'La parità tecnica si avvicina, ma non basta a innescare una migrazione ampia. Nell’esempio, l’attrito tra un buon modello e un sistema in produzione conta più del previsto.':'Il rincaro emerge, ma solo una parte della spesa si sposta su Amazon. La domanda si distribuisce anche su altri canali.'}</div><p>Somma trasparente: ${r.criteria.map(c=>c.points).join(' + ')} = ${score}. Osservazioni fittizie applicate ai criteri fissati; nessuna prova di eventi reali o di causalità.</p><div class="modal-actions"><button class="button" id="showFixed">Rivedi criteri</button><button class="button dark" id="learnFrom">Cosa posso imparare? →</button></div>`);$('#showFixed').onclick=()=>{$('#modal').close();recordDialog(r)};$('#learnFrom').onclick=()=>{$('#modal').close();showView('learn')}}
function renderLearn(){$('#content').innerHTML=`<section class="page-heading"><div><div class="eyebrow">06 / LEARN</div><h1>Impara a riconoscere il tuo pensiero.</h1><p>Non solo cosa hai previsto. Come sei arrivato a prevederlo.</p></div><span class="tag orange">PROFILO ILLUSTRATIVO</span></section><div class="wide-note">Esempio su 24 tesi fittizie, per mostrare Nesso dopo mesi di utilizzo. Non è un’analisi personale dei tuoi ragionamenti.</div><div class="metric-grid"><div class="metric"><small>Direzione del fenomeno</small><strong>78<small> /100</small></strong><small>Punto di forza nell’esempio</small></div><div class="metric"><small>Tempistiche</small><strong>46<small> /100</small></strong><small>Lo spazio per migliorare</small></div><div class="metric"><small>Tesi con dati quantitativi</small><strong>+18<small> pt</small></strong><small>Differenza illustrativa</small></div></div><div class="insight-grid"><article class="insight-card"><div class="eyebrow">UN PATTERN DA ESPLORARE</div><h2>Vedi bene la direzione.<br>Dai troppo poco tempo al cambiamento.</h2><p>Nell’esempio, 8 delle 12 tesi con esito parziale hanno anticipato il momento in cui il fenomeno sarebbe diventato visibile.</p><div class="chart-bars">${[42,51,58,64,70,78].map((v,i)=>`<div class="chart-col" style="height:${v*1.5}px;background:${i===5?'#e69572':'#c9d6bd'}"><b>${v}</b><span>${['Apr','Mag','Giu','Lug','Ago','Set'][i]}</span></div>`).join('')}</div><p style="margin-top:38px">Qualità della direzione prevista · Andamento fittizio</p></article><article class="insight-card"><div class="eyebrow">IL PROSSIMO ESERCIZIO</div><h2>Aggiungi una domanda alle tue prossime tesi.</h2><div class="challenge-card"><p>“Che cosa potrebbe rallentare questo cambiamento, anche se avessi ragione sulla direzione?”</p></div><p>Distingui tre tempi: quando il cambiamento diventa possibile, quando viene adottato e quando compare nei dati.</p><div class="divider"></div><div class="detail-label">UN’ALTRA IPOTESI SUL TUO METODO</div><p>Le tesi che partono da dati quantitativi potrebbero essere più verificabili. Servono più osservazioni per capire se sono anche più accurate.</p><button class="button dark" id="practice">Prova con una nuova tesi →</button></article></div>`;$('#practice').onclick=()=>newDialog()}
$('#newThesis').onclick=()=>newDialog();$$('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();showView('map')};$('#help').onclick=()=>modal(`${head('BENVENUTO NEL LABORATORIO')}<h2>Il dubbio è uno strumento.</h2><p><strong>Think → Map → Challenge → Save → Verify → Learn</strong></p><p>1. Parti da una tesi di esempio o scrivine una tua.<br>2. Clicca un passaggio per vedere le assunzioni.<br>3. Cambia lo scenario e osserva le conseguenze.<br>4. Fissa i criteri e salva nel diario.<br>5. Avvia una verifica simulata e leggi il feedback.</p><div class="wide-note">Demo con analisi e dati predefiniti. Le tesi salvate restano in questo browser. Nessun modello AI o monitoraggio esterno collegato.</div><div class="modal-actions"><button class="button dark" data-close>Inizia a esplorare</button></div>`);
 document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='n'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!$('#modal').open&&!['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)){e.preventDefault();newDialog()}});
initMap();$('#journalCount').textContent=String(saved.length+3).padStart(2,'0');
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'select_reasoning_node',title:'Esplora un passaggio',description:'Seleziona un nodo della mappa demo e mostra ipotesi e domanda critica.',inputSchema:{type:'object',properties:{node:{type:'integer',minimum:0,maximum:5}},required:['node'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>{if(!input||Object.keys(input).length!==1)throw Error('Fornisci solo node, da 0 a 5');return selectNode(input.node)}})).catch(()=>{})}catch{}}
